import assert from 'node:assert/strict';
import {test} from 'node:test';
import {makeRouter} from '../src/app.ts';
import {documentation, unrelatedHelper} from '../src/routes/accounts.ts';
import {auditCallback} from '../src/routes/orders.ts';

function createMockRes() {
  return {
    send(val) {
      return val;
    }
  };
}

test('route registration order and methods are preserved', () => {
  const router = makeRouter();
  assert.equal(router.routes.length, 5);
  assert.deepEqual(
    router.routes.map(r => ({ method: r.method, path: r.path })),
    [
      { method: 'GET', path: '/accounts/:id' },
      { method: 'POST', path: '/accounts' },
      { method: 'GET', path: '/health' },
      { method: 'GET', path: '/orders/:id' },
      { method: 'DELETE', path: '/orders/:id' }
    ]
  );
});

test('GET /accounts/:id handles success and forwards errors', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/accounts/:id');
  assert.ok(route);

  // Success
  let nextCalled = false;
  const res = createMockRes();
  const result = await route.handler({ id: 'acc-1' }, res, () => { nextCalled = true; });
  assert.equal(result, 'account:acc-1');
  assert.equal(nextCalled, false);

  // Failure
  let caughtError = null;
  await route.handler({ id: 'acc-1', fail: true }, res, (err) => { caughtError = err; });
  assert.ok(caughtError instanceof Error);
  assert.equal(caughtError.message, 'account read');
});

test('POST /accounts (named async function) handles success and forwards errors', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'POST' && r.path === '/accounts');
  assert.ok(route);

  // Success
  let nextCalled = false;
  const res = createMockRes();
  const result = await route.handler({ id: 'acc-2' }, res, () => { nextCalled = true; });
  assert.equal(result, 'created:acc-2');
  assert.equal(nextCalled, false);

  // Failure
  let caughtError = null;
  await route.handler({ id: 'acc-2', fail: true }, res, (err) => { caughtError = err; });
  assert.ok(caughtError instanceof Error);
  assert.equal(caughtError.message, 'account create');
});

test('GET /health synchronous route is preserved without wrapping', () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/health');
  assert.ok(route);

  let nextCalled = false;
  const res = createMockRes();
  const result = route.handler({ id: 'any' }, res, () => { nextCalled = true; });
  assert.equal(result, 'ok');
  assert.equal(nextCalled, false);
});

test('GET /orders/:id handles success and forwards errors', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'GET' && r.path === '/orders/:id');
  assert.ok(route);

  // Success
  let nextCalled = false;
  const res = createMockRes();
  const result = await route.handler({ id: 'order-abc' }, res, () => { nextCalled = true; });
  assert.equal(result, 'ORDER-ABC');
  assert.equal(nextCalled, false);

  // Failure
  let caughtError = null;
  await route.handler({ id: 'order-abc', fail: true }, res, (err) => { caughtError = err; });
  assert.ok(caughtError instanceof Error);
  assert.equal(caughtError.message, 'order read');
});

test('DELETE /orders/:id handles success and forwards errors', async () => {
  const router = makeRouter();
  const route = router.routes.find(r => r.method === 'DELETE' && r.path === '/orders/:id');
  assert.ok(route);

  // Success
  let nextCalled = false;
  const res = createMockRes();
  const result = await route.handler({ id: 'order-xyz' }, res, () => { nextCalled = true; });
  assert.equal(result, 'deleted:order-xyz');
  assert.equal(nextCalled, false);

  // Failure
  let caughtError = null;
  await route.handler({ id: 'order-xyz', fail: true }, res, (err) => { caughtError = err; });
  assert.ok(caughtError instanceof Error);
  assert.equal(caughtError.message, 'order delete');
});

test('unrelated async helpers and audit API are not wrapped', async () => {
  assert.equal(documentation, "router.get('/fake', async handler)");

  await assert.rejects(
    async () => { await unrelatedHelper(); },
    { name: 'Error', message: 'helper' }
  );

  await assert.rejects(
    async () => { await auditCallback(); },
    { name: 'Error', message: 'audit' }
  );
});

